def solution(candidates, target):
    res = []
    def backtrack(idx, path, curr_sum):
        if curr_sum == target:
            res.append(list(path))
            return
        if curr_sum > target:
            return
        for i in range(idx, len(candidates)):
            path.append(candidates[i])
            backtrack(i, path, curr_sum + candidates[i])
            path.pop()
    backtrack(0, [], 0)
    return res
